// Rounded quadratic boundaries retain every editable source vertex. Control
// points stay inside their local corner triangles: no Catmull-Rom overshoot.
export const regionTypes=['forest','grassland','meadow','snow','lake'];
export const hasRegionCurve=f=>f.closed&&regionTypes.includes(f.type)&&f.boundaryCurve?.type==='rounded-quadratic';
const distance=(a,b)=>Math.hypot(a[0]-b[0],a[1]-b[1]);
const lerp=(a,b,t)=>a.map((v,k)=>v+(b[k]-v)*t);
function corners(points,radius,pinned=[]){const pins=new Set(pinned);return points.map((p,i)=>{const a=points[(i+points.length-1)%points.length],b=points[(i+1)%points.length],da=distance(p,a),db=distance(p,b),r=pins.has(i)?0:Math.min(radius,da/2,db/2);return{p,entry:lerp(p,a,r/(da||1)),exit:lerp(p,b,r/(db||1))};});}
export function roundedRingPath(points,radius=.06,pinned=[],scale=100){const cs=corners(points,radius,pinned),xy=p=>p.map(v=>(v*scale).toFixed(5)).join(' ');return'M'+xy(cs[0].entry)+cs.map((c,i)=>' Q'+xy(c.p)+' '+xy(c.exit)+' L'+xy(cs[(i+1)%cs.length].entry)).join('')+' Z';}
export function sampleRoundedRing(points,radius=.06,pinned=[],step=.012,densify=false){const cs=corners(points,radius,pinned),out=[];for(let i=0;i<cs.length;i++){const c=cs[i],end=cs[(i+1)%cs.length].entry,n=Math.max(1,Math.ceil((distance(c.entry,c.p)+distance(c.p,c.exit))/step));out.push(c.entry);for(let j=1;j<=n;j++){const t=j/n,u=1-t;out.push([0,1].map(k=>u*u*c.entry[k]+2*u*t*c.p[k]+t*t*c.exit[k]));}const count=densify?Math.max(1,Math.ceil(distance(c.exit,end)/step)):1;for(let j=1;j<count;j++)out.push(lerp(c.exit,end,j/count));}return out.filter((p,i)=>!i||distance(p,out[i-1])>1e-10);}
const cache=new WeakMap();
export function regionRings(f,step=.012,densify=false){if(!hasRegionCurve(f))return[f.points,...(f.holes||[])];const key=JSON.stringify([f.points,f.holes,f.boundaryCurve,step,densify]),previous=cache.get(f);if(previous?.key===key)return previous.rings;const radius=f.boundaryCurve.radiusKm,rings=[sampleRoundedRing(f.points,radius,f.boundaryCurve.pinned,step,densify),...(f.holes||[]).map(h=>sampleRoundedRing(h,radius,[],step,densify))];cache.set(f,{key,rings});return rings;}
export function regionPath(f,scale=100){if(!hasRegionCurve(f))return null;return roundedRingPath(f.points,f.boundaryCurve.radiusKm,f.boundaryCurve.pinned,scale)+(f.holes||[]).map(h=>' '+roundedRingPath(h,f.boundaryCurve.radiusKm,[],scale)).join('');}
const pointSegment=(p,a,b)=>{const dx=b[0]-a[0],dy=b[1]-a[1],t=Math.max(0,Math.min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dy)/(dx*dx+dy*dy||1)));return distance(p,[a[0]+dx*t,a[1]+dy*t]);};
export function smoothRegionBoundaries(document){const endpoints=document.features.filter(f=>['river','waterfall'].includes(f.type)).flatMap(f=>[f.points[0],f.points.at(-1)]);let regions=0,holes=0;for(const f of document.features){if(!f.closed||!regionTypes.includes(f.type)||hasRegionCurve(f))continue;const pinned=[];if(f.type==='lake')for(let i=0;i<f.points.length;i++){const a=f.points[i],b=f.points[(i+1)%f.points.length];if(endpoints.some(p=>pointSegment(p,a,b)<.04)){pinned.push(i,(i+1)%f.points.length);}}f.boundaryCurve={type:'rounded-quadratic',radiusKm:.06,pinned:[...new Set(pinned)]};regions++;holes+=(f.holes||[]).length;}if(regions){document.regionCurveVersion=1;document.revision=(document.revision||0)+1;document.updatedAt=new Date().toISOString();}return{regions,holes};}
